const $=s=>document.querySelector(s), cats=['Todos','Impresiones 3D','Llaveros','Figuras','Papelería','Broches y calcomanías'];
let popularity={},rankingReady=false;const data=window.CREATIVE_CATALOG;let cart={},filter=document.body.dataset.category||'Todos';
try{cart=JSON.parse(localStorage.getItem('creative-cart'))||{}}catch{}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'C$ '+Number(n).toLocaleString('es-NI',{minimumFractionDigits:2,maximumFractionDigits:2});
const photo=p=>`<div class="photo">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}">`:'<svg aria-hidden="true"><use href="#photo-icon"/></svg><small>TU FOTO AQUÍ</small>'}${p.example?'<span class="badge">Producto de ejemplo</span>':''}</div>`;
function card(p){return `<article class="card">${p.name?`<a href="catalogo.html#${p.id}" aria-label="Ver ${esc(p.name)}">${photo(p)}</a>`:photo(p)}<div class="info"><span class="category">${esc(p.category)}</span><h3>${esc(p.name||'Tu próximo producto')}</h3><div class="price ${p.name?'':'empty-price'}">${p.name?money(p.price):'C$ —'} ${p.example?'<small>de ejemplo</small>':''}</div><div class="actions"><button data-add="${p.id}" ${p.name?'':'disabled'}>+ Al carrito</button><button class="buy" data-buy="${p.id}" ${p.name?'':'disabled'}>Comprar ya</button></div></div></article>`}
function render(){if(!$('#products')){renderSales();renderCart();return}let list=data.products.filter(p=>(filter==='Todos'||p.category===filter)&&(!$('#search').value||p.name.toLowerCase().includes($('#search').value.toLowerCase())));if($('#sort').value!=='default')list.sort((a,b)=>a.price==null?1:b.price==null?-1:($('#sort').value==='asc'?a.price-b.price:b.price-a.price));$('#products').innerHTML=list.map(card).join('')||'<p class="empty">No encontramos productos con esa búsqueda.</p>';renderSales();$('#result-count').textContent=list.filter(p=>p.name).length+' productos · Detalles hechos para ti';$('#filters').innerHTML=cats.map(c=>`<button class="filter ${filter===c?'active':''}" data-filter="${c}">${c}</button>`).join('');renderCart()}
function salesRows(){return data.products.filter(p=>p.name&&!p.example&&Number(popularity[p.id])>0).map(p=>({...p,sales:Number(popularity[p.id])})).sort((a,b)=>b.sales-a.sales||a.name.localeCompare(b.name))}
async function refreshPopularity(){try{const r=await fetch('/api/popularity');if(!r.ok)throw Error();const j=await r.json();popularity=j.counts;rankingReady=true}catch{rankingReady=false}renderSales()}
function trackRequest(items){if(location.protocol==='file:')return;fetch('/api/interest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({productIds:items.filter(x=>!x.p.example).map(x=>x.p.id)}),keepalive:true}).then(r=>{if(r.ok)return refreshPopularity()}).catch(()=>{})}
function renderSales(){if(!$('#bestsellers'))return;const rows=salesRows(),total=rows.reduce((n,p)=>n+p.sales,0);$('#sales-total').textContent=rankingReady?total.toLocaleString('es-NI'):'—';$('#sales-products').textContent=rankingReady?rows.length:'—';$('#sales-summary-note').textContent=!rankingReady?'Estadísticas disponibles al conectar el servidor.':total?'Cada elección cuenta una historia.':'El comienzo de muchas ideas.';$('#bestsellers').innerHTML=rows.length?rows.slice(0,5).map((p,i)=>`<a class="ranking-row" href="catalogo.html#${p.id}"><span class="rank">${i+1}</span><div class="rank-detail"><div class="rank-label"><strong>${esc(p.name)}</strong><span>${p.sales.toLocaleString('es-NI')}</span></div><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="width:${p.sales/rows[0].sales*100}%"></div></div></div></a>`).join(''):'<div class="sales-empty"><span class="empty-chart" aria-hidden="true"><i></i><i></i><i></i><i></i></span><strong>Los próximos favoritos están por descubrirse</strong><p>Cuando lleguen las primeras solicitudes, verás aquí los productos más elegidos.</p></div>';}
function toast(t){$('#toast').textContent=t;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),2800)}
function entries(){return Object.entries(cart).map(([id,q])=>({p:data.products.find(x=>x.id===id),q})).filter(x=>x.p?.name&&Number.isInteger(x.q)&&x.q>0)}
function renderCart(){let items=entries();$('#count').textContent=items.reduce((n,x)=>n+x.q,0);$('#cart-content').innerHTML=items.length?items.map(({p,q})=>`<div class="cart-row"><div><b>${esc(p.name)}</b><p class="note">${money(p.price)}${p.example?' · Ejemplo':''}</p><button class="text-button" data-remove="${p.id}">Eliminar</button></div><div class="qty"><button data-qty="${p.id}" data-delta="-1" aria-label="Disminuir cantidad">−</button><span>${q}</span><button data-qty="${p.id}" data-delta="1" aria-label="Aumentar cantidad">+</button></div></div>`).join('')+`<div class="total"><span>Subtotal</span><span>${money(items.reduce((n,x)=>n+x.p.price*x.q,0))}</span></div><button class="btn green full" id="checkout">Pedir por WhatsApp</button><p class="note">Confirmaremos disponibilidad, envío y pago en el chat. El mensaje incluirá los enlaces de los productos.</p>`:'<p class="empty">Tu carrito está esperando un detalle especial.</p>';try{localStorage.setItem('creative-cart',JSON.stringify(cart))}catch{}}
function buy(items){const isLocal=location.protocol==='file:'||['localhost','127.0.0.1'].includes(location.hostname);const root=isLocal?'':new URL('catalogo.html',location.href).href;let message='¡Hola, Creative Design! Me interesan estos productos:\n\n'+items.map(({p,q})=>`${q} × ${p.name}${p.example?' (PRODUCTO DE EJEMPLO)':''}\n${money(p.price)} c/u\n${root?root+'#'+p.id:'Referencia: '+p.id+' (prueba local)'}`).join('\n\n')+'\n\nSubtotal: '+money(items.reduce((n,x)=>n+x.p.price*x.q,0))+'\n¿Me confirman disponibilidad y costo de envío?';openOrder(items,message)}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.add){cart[b.dataset.add]=(cart[b.dataset.add]||0)+1;renderCart();toast('Agregado a tu carrito')}if(b.dataset.buy)buy([{p:data.products.find(x=>x.id===b.dataset.buy),q:1}]);if(b.dataset.filter||b.dataset.cat){filter=b.dataset.filter||b.dataset.cat;render()}if(b.dataset.qty){cart[b.dataset.qty]+=Number(b.dataset.delta);if(cart[b.dataset.qty]<=0)delete cart[b.dataset.qty];renderCart()}if(b.dataset.remove){delete cart[b.dataset.remove];renderCart()}if(b.id==='checkout')buy(entries());if(b.classList.contains('close'))b.closest('dialog').close()});
$('#search').addEventListener('input',()=>{if($('#products'))render()});$('#search').addEventListener('keydown',e=>{if(e.key==='Enter'&&!$('#products'))location.href='catalogo.html?q='+encodeURIComponent($('#search').value)});$('#sort')?.addEventListener('change',render);$('#cart-open').onclick=()=>$('#cart-dialog').showModal();
function showProduct(){const p=data.products.find(x=>'#'+x.id===location.hash);if(!p?.name)return;$('#product-content').innerHTML=photo(p)+`<span class="category">${esc(p.category)}</span><h2>${esc(p.name)}</h2><div class="price">${money(p.price)}</div>${p.example?'<p class="note">Esta ficha es un ejemplo para mostrar cómo se verá tu producto.</p>':''}<div class="actions"><button data-add="${p.id}">+ Al carrito</button><button class="buy" data-buy="${p.id}">Comprar ya</button></div>`;if(!$('#product-dialog').open)$('#product-dialog').showModal()}
window.addEventListener('hashchange',showProduct);$('#product-dialog').addEventListener('close',()=>{if(location.hash.startsWith('#producto-'))history.replaceState(null,'',location.pathname+location.search)});
let orderItems=[],orderMessage='',orderFiles=[],orderToken=0;
async function openOrder(items,message){
 orderItems=items;orderMessage=message;orderFiles=[];const token=++orderToken;
 $('#order-chat').href='https://wa.me/50589039913?text='+encodeURIComponent(message);
 $('#share-preview').innerHTML=items.filter(x=>x.p.image).map(({p})=>`<img src="${esc(p.image)}" alt="${esc(p.name)}">`).join('');
 $('#photo-downloads').innerHTML='';$('#share-photo').disabled=true;
 $('#share-note').textContent='Preparando las fotos…';
 if(!$('#order-dialog').open)$('#order-dialog').showModal();
 const files=await Promise.all(items.filter(x=>x.p.image).map(async({p})=>{try{const response=await fetch(p.image);if(!response.ok)throw Error();const blob=await response.blob();if(!['image/png','image/jpeg','image/webp'].includes(blob.type))return null;return new File([blob],p.id+'.'+(blob.type==='image/png'?'png':blob.type==='image/webp'?'webp':'jpg'),{type:blob.type})}catch{return null}}));
 if(token!==orderToken)return;orderFiles=files.filter(Boolean);
 let shareable=false;try{shareable=orderFiles.length>0&&!!navigator.canShare?.({files:orderFiles})}catch{}
 $('#share-photo').disabled=!shareable;
 $('#share-note').textContent=shareable?'Comparte las fotos desde el menú de tu dispositivo. También puedes abrir directamente el chat de la tienda.':items.some(x=>x.p.image)?'Este navegador no puede compartir estas fotos directamente. Descarga la foto y adjúntala en el chat.':'Este producto aún no tiene foto. Puedes continuar con el detalle del pedido.';
 $('#photo-downloads').innerHTML=items.filter(x=>x.p.image).map(({p})=>`<p><a href="${esc(p.image)}" download="${p.id}.jpg" target="_blank" rel="noopener">Descargar foto: ${esc(p.name)}</a></p>`).join('');
}
$('#order-chat').addEventListener('click',()=>trackRequest(orderItems));
$('#share-photo').onclick=async()=>{try{await navigator.share({files:orderFiles,title:'Pedido Creative Design',text:orderMessage})}catch(e){if(e.name!=='AbortError')toast('No se pudo compartir. Descarga la foto y adjúntala en WhatsApp.')}};

$('#search').value=new URLSearchParams(location.search).get('q')||'';render();showProduct();if(location.protocol!=='file:'){refreshPopularity();setInterval(refreshPopularity,30000)}